scriptdefs
= BattleFrontier_BattlePikeThreePathRoom_EventScript_GivePikeQueenHint
applymovement LOCALID_PIKE_HINT_GIVER BattleFrontier_BattlePikeThreePathRoom_Movement_HintGiverApproachPlayer
waitmovement 0
lockall
msgbox	Es tut mir leid, sagen zu müssen…Ein schreckliches Ereignis, ja, ein grauenhaftes, steht dir bevor…Ich bitte dich eindringlich, äußerste Vorsicht walten zu lassen und dich auf das Schlimmste einzustellen…
releaseall
applymovement LOCALID_PIKE_HINT_GIVER BattleFrontier_BattlePikeThreePathRoom_Movement_HintGiverReturnToPos
waitmovement 0
setvar VAR_TEMP_5 255
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_SetHintRoom
pike_sethintroom
goto_if_eq VAR_RESULT TRUE BattleFrontier_BattlePikeThreePathRoom_EventScript_SetPikeQueenHint
setvar VAR_TEMP_5 255
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_SetPikeQueenHint
setvar VAR_TEMP_5 1
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_ResumeChallenge
lockall
msgbox	Wir haben auf deine Rückkehr gewartet…Bevor du deine Battle-Choice-Herausforderung fortsetzt, lass mich den Spielstand sichern…
waitmessage
pike_save CHALLENGE_STATUS_SAVING
playse SE_SAVE
waitse
frontier_set FRONTIER_DATA_PAUSED FALSE
setvar VAR_TEMP_CHALLENGE_STATUS 255
special SavePlayerParty
frontier_setpartyorder FRONTIER_PARTY_SIZE
msgbox	Genieße bitte deine Battle-Choice-Herausforderung…
closemessage
releaseall
frontier_settrainers
frontier_set FRONTIER_DATA_CHALLENGE_STATUS 99
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpToLobby
warp BattleFrontier_BattlePikeLobby 5 6
waitstate
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_GetChallengeStatus
frontier_getstatus
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_NoTurningBack
setvar VAR_TEMP_3 0
setvar VAR_TEMP_2 0
lockall
msgbox	Der Weg ist versperrt! Und es gibt kein Zurück mehr…
closemessage
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_SetEnteredRoom
setvar VAR_TEMP_3 1
setvar VAR_TEMP_2 1
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_RightRoomWarp
setvar VAR_0x8007 PIKE_ROOM_RIGHT
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_RoomWarp
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_RoomWarp
pike_get PIKE_DATA_WIN_STREAK
addvar VAR_RESULT 1
pike_set PIKE_DATA_WIN_STREAK VAR_RESULT
frontier_get FRONTIER_DATA_BATTLE_NUM
addvar VAR_RESULT 1
frontier_set FRONTIER_DATA_BATTLE_NUM VAR_RESULT
pike_setnextroom
pike_getroomtype
switch VAR_RESULT
case PIKE_ROOM_SINGLE_BATTLE BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
case PIKE_ROOM_HEAL_FULL BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
case PIKE_ROOM_NPC BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
case PIKE_ROOM_STATUS BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
case PIKE_ROOM_HEAL_PART BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
case PIKE_ROOM_WILD_MONS BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpWildMonRoom
case PIKE_ROOM_HARD_BATTLE BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
case PIKE_ROOM_DOUBLE_BATTLE BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
case PIKE_ROOM_BRAIN BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpNPCRoom
applymovement LOCALID_PLAYER BattleFrontier_BattlePikeRoom_Movement_HidePlayer
waitmovement 0
call BattleFrontier_BattlePike_EventScript_CloseCurtain
warpsilent BattleFrontier_BattlePikeRoomNormal 4 7
waitstate
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_WarpWildMonRoom
applymovement LOCALID_PLAYER BattleFrontier_BattlePikeRoom_Movement_HidePlayer
waitmovement 0
call BattleFrontier_BattlePike_EventScript_CloseCurtain
warpsilent BattleFrontier_BattlePikeRoomWildMons 4 19
waitstate
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_CenterRoomWarp
setvar VAR_0x8007 PIKE_ROOM_CENTER
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_RoomWarp
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_LeftRoomWarp
setvar VAR_0x8007 PIKE_ROOM_LEFT
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_RoomWarp
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_HintGiver
pike_gethint
goto_if_eq VAR_RESULT PIKE_HINT_BRAIN BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveBrainHint
lock
faceplayer
msgboxyesno	I beg your pardon, but…Are you perhaps finding it difficult to choose your path?
switch VAR_RESULT
case YES BattleFrontier_BattlePikeThreePathRoom_EventScript_AcceptHint
case NO BattleFrontier_BattlePikeThreePathRoom_EventScript_DeclineHint
case MULTI_B_PRESSED BattleFrontier_BattlePikeThreePathRoom_EventScript_DeclineHint
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_DeclineHint
msgbox	Ich verstehe… Ich entschuldige mich für meine Unverschämtheit…
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_AcceptHint
pike_gethintroomid
switch VAR_RESULT
case PIKE_ROOM_LEFT BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveLeftRoomHint
case PIKE_ROOM_CENTER BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveCenterRoomHint
case PIKE_ROOM_RIGHT BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveRightRoomHint
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveRightRoomHint
msgbox	Ah, lass mich sehen… Da ist etwas mit dem Weg auf der rechten Seite…
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveHint
= BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveHint
pike_gethint
switch VAR_RESULT
case PIKE_HINT_NOSTALGIA BattleFrontier_BattlePikeThreePathRoom_EventScript_HintNostalgia
case PIKE_HINT_WHISPERING BattleFrontier_BattlePikeThreePathRoom_EventScript_HintWhispering
case PIKE_HINT_POKEMON BattleFrontier_BattlePikeThreePathRoom_EventScript_HintPokemon
case PIKE_HINT_PEOPLE BattleFrontier_BattlePikeThreePathRoom_EventScript_HintPeople
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_HintPeople
msgbox	Ist es… Ein TRAINER? Ich spüre die Anwesenheit von Menschen…
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_HintPokemon
msgbox	Es scheint, als würde ein deutlicher Duft von POKéMON darum herumwehen…
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_HintWhispering
msgbox	Ich glaube, ich habe etwas gehört… Es könnte ein Flüstern gewesen sein…
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_HintNostalgia
msgbox	Aus irgendeinem seltsamen Grund verspürte ich eine Welle der Wehmut, die davon ausging…
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveCenterRoomHint
msgbox	Ah, lass mich sehen… Da ist etwas mit dem Weg in der Mitte…
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveHint
= BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveLeftRoomHint
msgbox	Ah, lass mich sehen… Da ist etwas mit dem Weg auf der linken Seite…
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveHint
= BattleFrontier_BattlePikeThreePathRoom_EventScript_GiveBrainHint
lock
faceplayer
msgbox	Von jedem Weg spüre ich eine furchteinflößende Anwesenheit…
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_Attendant
frontier_get FRONTIER_DATA_BATTLE_NUM  @ Room number
switch VAR_RESULT
case 1 BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom1
case 3 BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom3
case 5 BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom5
case 7 BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom7
case 9 BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom9
case 11 BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom11
case 13 BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom13
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom13
lock
faceplayer
msgbox	Du befindest dich derzeit im 13. Raum…
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_AskContinueChallenge
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_AskContinueChallenge
msgboxyesno	Will you continue with your challenge?
switch VAR_RESULT
case NO BattleFrontier_BattlePikeThreePathRoom_EventScript_AskSaveChallenge
case MULTI_B_PRESSED BattleFrontier_BattlePikeThreePathRoom_EventScript_AskSaveChallenge
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_AskSaveChallenge
msgboxyesno	Would you like to save your challenge and quit the game for now?
switch VAR_RESULT
case YES BattleFrontier_BattlePikeThreePathRoom_EventScript_PauseChallenge
case NO BattleFrontier_BattlePikeThreePathRoom_EventScript_AskRetireChallenge
case MULTI_B_PRESSED BattleFrontier_BattlePikeThreePathRoom_EventScript_AskRetireChallenge
release
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_AskRetireChallenge
msgbox	Möchtest du deine Battle-Choice-Herausforderung aufgeben?
waitmessage
multichoicedefault 20 8 MULTI_YESNO 1 FALSE
switch VAR_RESULT
case 0 BattleFrontier_BattlePike_EventScript_Retire
release
end
= BattleFrontier_BattlePike_EventScript_Retire
frontier_set FRONTIER_DATA_CHALLENGE_STATUS CHALLENGE_STATUS_LOST
warp BattleFrontier_BattlePikeLobby 5 6
waitstate
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_PauseChallenge
frontier_saveparty
msgbox	Ich speichere deine Daten… Einen Moment Geduld bitte…
waitmessage
special LoadPlayerParty
pike_save CHALLENGE_STATUS_PAUSED
playse SE_SAVE
waitse
fadescreen FADE_TO_BLACK
frontier_reset
end
= BattleFrontier_BattlePikeThreePathRoom_EventScript_AttendantRoom11
lock
faceplayer
msgbox	Du befindest dich derzeit im 11. Raum…
goto BattleFrontier_BattlePikeThreePathRoom_EventScript_AskContinueChallenge
end
